from save_review import save
import json,re
from pathlib import Path
D=Path(__file__).resolve().parents[2];corpus={a['number']:a for a in json.loads((D/'全书分段底稿.json').read_text())}
def tableterms(n,ed,start):
 bs={int(b['id'][-4:]):b for b in corpus[n]['blocks']};ts=[]
 for i,b in bs.items():
  if i<start or b.get('language')!='en' or i+1 not in bs or bs[i+1].get('language')!='zh':continue
  en=re.split(r'\s*[-—/]\s*|\(former\)',b['text'],maxsplit=1)[0].strip()
  zh=re.split(r'\s*[-—/]\s*|（|\(',ed.get(i+1,bs[i+1]['text']),maxsplit=1)[0].strip()
  if en and zh and len(en)<60:ts.append((en,zh))
 return ts
ed={2:'红衣主教世界是文明世界的一个子类，同样能够自给自足，科技水平至少达到中等程度。这些世界隶属国教，由国教会直接统治；行星总督同时也是一位红衣主教。神殿与其他宗教圣所往往覆盖星球的大片区域。',3:'Known Cardinal Worlds 著名红衣主教世界',13:'迪马默——朦胧星域；帝国。',17:'埃斯潘多——极限星域；帝国。',23:'加塔拉莫——太阳星域；帝国。',33:'奥卡西斯（原红衣主教世界）——极限星域；现归属不明，原属帝国；现为死寂世界。',35:'奥菲利亚七号——暴风星域；帝国；同时被列为圣地世界和铸造世界。',45:'圣洁星——帝国；291.M37年圣洁星冲突的发生地。',49:'恶棍之陨——太阳星域；帝国。',53:'瓦勒多尔（原红衣主教世界）——更早曾是名为杜瑞尔的少女世界，现已毁灭。'}
save(866,ed,title='红衣主教世界 Cardinal World',notes={2:'Cardinal 指红衣主教，与核心术语统一；Ministorum 是国教会这一组织。',35:'英文并列三种世界分类，可能对应不同资料或时期，照录并保留待核。',49:'Segmentum Solar 为太阳星域，原译太平星域错误。'},terms=[('Cardinal World','红衣主教世界')]+tableterms(866,ed,4))
ed={2:'墓地世界，有时也称安葬世界，是帝国的一种世界分类，与圣地世界有些相似。这类星球的大片地域用于安葬死者、守护陵墓。它们可能是某场巨大战役的遗址，也可能遍布宏伟陵寝，每座都属于一位帝国贵族。少数墓地世界则截然不同：无边无际的简朴墓园中，安葬着邻近巢都世界居民的遗骸。',7:'塞尔图斯次星——朦胧星域；普拉加次星区；也是战争世界。',9:'克里普托斯——朦胧星域；卡利西斯星区、德鲁苏斯边区。',13:'赛尔达——朦胧星域；卡利西斯星区、边陲；由赛维安帝国控制。',15:'德梅里姆——编号MX/44219/M/AE；瑞西迪厄斯星系；也是战争世界。',19:'格拉尼索——朦胧星域；卡利西斯星区、戈尔根纳疆域。',25:'朝圣者之滞——朦胧星域；卡利西斯星区、哈冼录深渊。',27:'普雷斯特·迈拉——朦胧星域；卡利西斯星区、约西亚疆域。',29:'安全港——维达尔星区；除圣地守卫外，无人居住。',31:'塔尔——朦胧星域；阿斯凯隆星区。'}
save(867,ed,notes={2:'care for the dead 指安葬及看护死者的安息之所，避免译成日常照料活人的“照顾”。',9:'此处 Cryptus 是卡利西斯星区的墓地行星；不与极限星域的同名星系统一为一个地理对象。',13:'Severan Dominate 是政体名，依核心表为赛维安帝国，不是“塞韦兰统治者”。',15:'MX/44219/M/AE 的具体编码性质原文未解释，保留编号，不擅自将其当作已知星域名。'},terms=[('Cemetery World','墓地世界'),('Burial World','安葬世界'),('Cryptus (Cemetery World)','克里普托斯（墓地世界）')]+[(e,z) for e,z in tableterms(867,ed,4) if e!='Cryptus'])
ed={2:'文明世界，即γ类世界，是帝国行星分类中的一种。',6:'在帝国的各类定居世界中，文明世界最为常见。这里的“文明”指城市景观，并不意味着居民讲究礼仪或社会风气文明。这些世界能够自给自足，人口主要集中于大型城市或其他都市聚居区，由星球自身的农业生产供养。各地科技与社会发展程度不一，但大多接近帝国当时的通常水平。帝国的大多数国家机构一般都在当地设有分支。按分类标准，文明世界的人口介于1500万至100亿之间，什一税等级从 Solutio Extremis 到 Exactis Tertius；原稿暂译“第三级高等”至“第一级初等”。',9:'红衣主教世界（cc）',11:'花园世界（cg）',13:'矿业世界（cm）',20:'阿弥斯陶主星——朦胧星域；帝国。',24:'卡特吉努斯（原文明世界）——星域归属不明，位于太阳星域边界之外不远处；现属帝国，荷鲁斯之乱期间曾归混沌；也是精炼世界，现列为死寂世界。',26:'科德里斯（原文明世界）——极限星域；帝国；被毁前人口约1600万，行星防卫部队约5万人；现为死寂世界。',38:'艾丽西亚——太阳星域；帝国。',40:'埃利西亚尔——朦胧星域；莫德伦领地；帝国。',44:'机遇星——帝国；圣洁星冲突发生地之一。',66:'月球——太阳星域、太阳星系；帝国；人口数十亿；泰拉的卫星，也被列为死亡世界。',76:'莫德伦主星——朦胧星域；莫德伦领地；帝国。',90:'损害星——朦胧星域；莫德伦领地；帝国。',98:'塔纳克雷格——帝国；人口不详，底稿另记约一两百万人；同时列为死寂世界。'}
bs={int(b['id'][-4:]):b for b in corpus[868]['blocks']}
for i,b in bs.items():
 if i<15 or b.get('language')!='en' or i+1 not in bs:continue
 s=ed.get(i+1,bs[i+1]['text'])
 if 'Dead World' in b['text']:s=s.replace('死亡世界','死寂世界')
 if s!=bs[i+1]['text']:ed[i+1]=s
save(868,ed,notes={2:'γ是希腊字母分类代码，不是等级序号。',6:'修正原译数字分组；税级中文尚未直核官方文本，保留英文及原稿暂译。',40:'Elysiar 与 Elysia 拼写不同，分别保留“埃利西亚尔”和既定“艾丽西亚”，不把两颗行星合并。',66:'Luna 即月球。此行原文确为 Death World，保留死亡世界，不套用 Dead World 的死寂世界。',98:'人口未知、一两百万与死寂世界三项并列，可能来自不同资料或时期，保留差异并待核。'},terms=[('Civilised World','文明世界'),('Solutio Extremis','第三级高等'),('Exactis Tertius','第一级初等'),('Elysiar','埃利西亚尔')]+tableterms(868,ed,15))
